          "upset stomach, loose stools, nausea, and drowsiness"
        ],
        "reference_indexes": [
          0
        ]
      },
      {
        "type": "heading",
        "snippet": "Common and Mild Side Effects"
      },
      {
        "type": "list",
        "list": [
          {
            "snippet": "Digestive issues: Nausea, vomiting, diarrhea, or abdominal discomfort."
          },
          {
            "snippet": "Drowsiness: Feeling tired, sedated, or sleepy, especially at higher doses or when combined with alcohol."
          },
          {
            "snippet": "Headaches: Occasional mild head pain or dizziness."
          }
        ],
        "reference_indexes": [
          1,
          2,
          3,
          4
        ]
