      {
        "type": "heading",
        "snippet": "Rare and Serious Risks"
      },
      {
        "type": "list",
        "list": [
          {
            "snippet": "Liver injury: Rare reports link the supplement to hepatotoxicity or elevated liver enzymes."
          },
          {
            "snippet": "Thyroid changes: It may increase thyroid hormone levels, which can cause problems for people with hyperthyroidism."
          },
          {
            "snippet": "Increased testosterone: It can raise testosterone levels, which might be a concern for hormone-sensitive prostate cancer."
          }
        ],
        "reference_indexes": [
